-- Emulation of the two PostgreSQL partial UNIQUE indexes of the automation schema. MySQL has no partial
-- indexes; each is rebuilt with a stored generated column that is NULL for rows outside the predicate
-- (NULLs never collide in a unique index), so the invariant is enforced by the database, not by code.
--   alarm_episodes_active   UNIQUE (tenant_id, policy_key, subject_id, dimension) WHERE state = 'active'
--   auto_rules_resource_key UNIQUE (tenant_id, resource_key) WHERE resource_key IS NOT NULL AND deleted_at IS NULL
-- Generated by hand, applied after 010 by the same runner (session variables need its single connection).
-- @@
SET @tp_p1 := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'alarm_episodes' AND column_name = 'active_marker')
-- @@
SET @tp_p1_sql := IF(@tp_p1 = 0, 'ALTER TABLE alarm_episodes ADD COLUMN `active_marker` TINYINT GENERATED ALWAYS AS (IF(`state` = ''active'', 1, NULL)) STORED NULL', 'SELECT 1')
-- @@
PREPARE tp_p1_stmt FROM @tp_p1_sql
-- @@
EXECUTE tp_p1_stmt
-- @@
DEALLOCATE PREPARE tp_p1_stmt
-- @@
SET @tp_p2 := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'alarm_episodes' AND index_name = 'alarm_episodes_active')
-- @@
SET @tp_p2_sql := IF(@tp_p2 = 0, 'CREATE UNIQUE INDEX alarm_episodes_active ON alarm_episodes (`tenant_id`, `policy_key`, `subject_id`, `dimension`, `active_marker`)', 'SELECT 1')
-- @@
PREPARE tp_p2_stmt FROM @tp_p2_sql
-- @@
EXECUTE tp_p2_stmt
-- @@
DEALLOCATE PREPARE tp_p2_stmt
-- @@
SET @tp_p3 := (SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'auto_rules' AND column_name = 'live_resource_key')
-- @@
SET @tp_p3_sql := IF(@tp_p3 = 0, 'ALTER TABLE auto_rules ADD COLUMN `live_resource_key` VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (IF(`resource_key` IS NOT NULL AND `deleted_at` IS NULL, `resource_key`, NULL)) STORED NULL', 'SELECT 1')
-- @@
PREPARE tp_p3_stmt FROM @tp_p3_sql
-- @@
EXECUTE tp_p3_stmt
-- @@
DEALLOCATE PREPARE tp_p3_stmt
-- @@
SET @tp_p4 := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'auto_rules' AND index_name = 'auto_rules_resource_key')
-- @@
SET @tp_p4_sql := IF(@tp_p4 = 0, 'CREATE UNIQUE INDEX auto_rules_resource_key ON auto_rules (`tenant_id`, `live_resource_key`)', 'SELECT 1')
-- @@
PREPARE tp_p4_stmt FROM @tp_p4_sql
-- @@
EXECUTE tp_p4_stmt
-- @@
DEALLOCATE PREPARE tp_p4_stmt
